practice.solution:
def parse_reply(text):
    if text.startswith('FINAL '):
        return ['final', text[6:]]
    if text.startswith('CALL '):
        rest = text[5:]
        i = rest.find(' ')
        if i < 0:
            return ['call', rest, '']
        return ['call', rest[:i], rest[i + 1:]]
    return ['error', text]

