practice.solution:
def validate(schema, args):
    given = {}
    for k, v in args:
        given[k] = v
    for name, tname, req in schema:
        if name not in given:
            if req:
                return 'missing ' + name
            continue
        v = given[name]
        if tname == 'int':
            if not (isinstance(v, int) and not isinstance(v, bool)):
                return 'bad type ' + name
        else:
            if not isinstance(v, str):
                return 'bad type ' + name
    return 'ok'

