def waves(tasks):
    done = []
    out = []
    while True:
        wave = []
        for name, deps in tasks:
            if name in done:
                continue
            ok = True
            for d in deps:
                if d not in done:
                    ok = False
            if ok:
                wave.append(name)
        if not wave:
            break
        out.append(wave)
        done = done + wave
    return out

