practice.solution:
def guarded_run(calls, allowlist, max_steps, budget):
    run = 0
    total = 0
    for tool, cost in calls:
        if run >= max_steps:
            return [run, total, 'step limit']
        if tool not in allowlist:
            continue
        if total + cost > budget:
            return [run, total, 'budget']
        run += 1
        total += cost
    return [run, total, 'finished']

